import time
import itertools

def get_best_schedule(workload, num_seqs):
    """
    Conflict-window-block-packing optimizer.

    Approach: (1) build a conflict graph from transaction key sets via
    union-find on shared keys, partitioning transactions into connected
    conflict clusters; (2) order each cluster — brute-force optimal for
    clusters of <=7 txns (<=5040 true-cost evals, cached), greedy
    cheapest-insertion for larger ones; (3) interleave cluster orderings by
    repeatedly appending the cluster-next-transaction that minimizes the true
    simulator prefix cost; (4) polish the full permutation with a
    ruin-and-recreate loop (conflict-linked or window ruin, true-best
    reinsertion) until the shared per-workload deadline. Identity permutation
    is retained as a valid fallback, and a tuple-key cost cache memoizes all
    simulator calls. Hard ~100s per-workload deadline keeps three workloads
    inside the 360s total limit.
    """
    n = workload.num_txns
    if n == 0:
        return 0, []
    deadline = time.time() + 100.0
    cache = {}

    def cost(seq):
        key = tuple(seq)
        c = cache.get(key)
        if c is None:
            c = workload.get_opt_seq_cost(list(seq))
            cache[key] = c
        return c

    # Fallback: identity permutation (always valid).
    best_seq = list(range(n))
    best_cost = cost(best_seq)

    # --- Step 1: conflict clusters via union-find on shared keys. ---
    txn_keys = {}
    try:
        for t in range(n):
            ops = workload.get_txn_ops(t)
            keys = set()
            for op in ops:
                try:
                    keys.add(op.key)
                except AttributeError:
                    try:
                        keys.add(op[1])
                    except Exception:
                        pass
            txn_keys[t] = keys
    except Exception:
        txn_keys = {}

    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    if txn_keys:
        key_map = {}
        for t in range(n):
            for k in txn_keys.get(t, set()):
                if k in key_map:
                    a, b = find(key_map[k]), find(t)
                    if a != b:
                        parent[a] = b
                else:
                    key_map[k] = t

    clusters = {}
    for t in range(n):
        clusters.setdefault(find(t), []).append(t)
    cluster_lists = [sorted(members) for members in clusters.values()]

    # --- Step 2: order each cluster. ---
    BRUTE_LIMIT = 7
    ordered_clusters = []
    for members in cluster_lists:
        m = len(members)
        if m == 1:
            ordered_clusters.append(list(members))
            continue
        if m <= BRUTE_LIMIT:
            best_ord, best_c = None, None
            for perm in itertools.permutations(members):
                if time.time() > deadline:
                    break
                p = list(perm)
                c = cost(p)
                if best_c is None or c < best_c:
                    best_c, best_ord = c, p
            if best_ord is None:
                best_ord = list(members)
            ordered_clusters.append(best_ord)
        else:
            # Greedy cheapest-insertion using true cost.
            cur = [members[0]]
            for t in members[1:]:
                if time.time() > deadline:
                    cur.extend(members[members.index(t):])
                    break
                best_pos, best_c = 0, None
                for pos in range(len(cur) + 1):
                    cand = cur[:pos] + [t] + cur[pos:]
                    c = cost(cand)
                    if best_c is None or c < best_c:
                        best_c, best_pos = c, pos
                cur.insert(best_pos, t)
            ordered_clusters.append(cur)

    # --- Step 3: interleave cluster orderings by true prefix cost. ---
    # Each cluster contributes a queue; at each step append the head of the
    # cluster whose head minimizes the true prefix cost of the merged sequence.
    queues = [list(c) for c in ordered_clusters]
    merged = []
    heads = [q.pop(0) for q in queues]
    while any(h is not None for h in heads):
        if time.time() > deadline:
            # Flush remaining in cluster order.
            for h, q in zip(heads, queues):
                if h is not None:
                    merged.append(h)
                merged.extend(q)
                while q:
                    q.pop()
            break
        best_t, best_i, best_c = None, None, None
        for i, h in enumerate(heads):
            if h is None:
                continue
            c = cost(merged + [h])
            if best_c is None or c < best_c:
                best_c, best_t, best_i = c, h, i
        merged.append(best_t)
        if queues[best_i]:
            heads[best_i] = queues[best_i].pop(0)
        else:
            heads[best_i] = None

    if len(merged) == n and cost(merged) < best_cost:
        best_cost, best_seq = cost(merged), merged[:]

    # --- Step 4: ruin-and-recreate polish within remaining budget. ---
    def ruin_block(seq):
        if txn_keys and random.random() < 0.5:
            seed = random.randrange(n)
            block = {seed}
            seed_keys = txn_keys.get(seed, set())
            for t in range(n):
                if t != seed and txn_keys.get(t, set()) & seed_keys:
                    block.add(t)
                    if len(block) >= 25:
                        break
            if len(block) < 3:
                return None
            return [t for t in seq if t in block]
        lo = random.randrange(n)
        size = random.randint(10, min(25, n))
        hi = min(n, lo + size)
        return seq[lo:hi]

    def recreate(seq, removed):
        cur = seq[:]
        for t in removed:
            best_pos, best_c = None, None
            for pos in range(len(cur) + 1):
                cand = cur[:pos] + [t] + cur[pos:]
                c = cost(cand)
                if best_c is None or c < best_c:
                    best_c, best_pos = c, pos
                if time.time() > deadline:
                    break
            cur = cur[:best_pos] + [t] + cur[best_pos:]
        base = cost(cur)
        for i in range(len(cur) - 1):
            if time.time() > deadline:
                break
            cand = cur[:]
            cand[i], cand[i + 1] = cand[i + 1], cand[i]
            c = cost(cand)
            if c < base:
                cur, base = cand, c
        return cur

    cur_seq, cur_cost = best_seq[:], best_cost
    while time.time() < deadline:
        removed = ruin_block(cur_seq)
        if not removed:
            continue
        rem_set = set(removed)
        partial = [t for t in cur_seq if t not in rem_set]
        cand = recreate(partial, removed)
        c = cost(cand)
        if c < cur_cost:
            cur_seq, cur_cost = cand, c
            if c < best_cost:
                best_cost, best_seq = c, cand[:]
        elif c == cur_cost and random.random() < 0.3:
            cur_seq, cur_cost = cand, c
        elif random.random() < 0.05:
            cur_seq, cur_cost = best_seq[:], best_cost

    assert len(set(best_seq)) == n
    return best_cost, best_seq

